{"id":"7fd14fc4-a27b-46dc-b8bf-92911604e84f","inserted_at":"2026-07-15T06:46:38.048731+00:00","updated_at":"2026-07-15T06:46:38.048731+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- =========================================================================================\r\n-- SYNC PROFILES FIX (V2)\r\n-- =========================================================================================\r\n-- Questo script prende tutti gli utenti attualmente loggati (in auth.users) \r\n-- e ricrea la loro riga nella tabella public.profiles, dato che il reset l'aveva svuotata!\r\n\r\nINSERT INTO public.profiles (id, total_tokens, total_xp, total_co2, total_liters_water, experience_level, is_premium, flow_role)\r\nSELECT id, 0, 0, 0, 0, 1, false, 'LOTO Explorer'\r\nFROM auth.users\r\nON CONFLICT (id) DO NOTHING;","content_id":"7fd14fc4-a27b-46dc-b8bf-92911604e84f","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
